        ("struct Translate<F> {\n    translate: F,\n    ran: AtomicBool,\n}\n\nimpl<F: Fn(&[u8]) -> Result<HostShader, String> + Send + Sync> Converter for Translate<F> {\n    fn id(&self) -> &'static str {\n        \"shader.dxil\"\n    }\n    fn version(&self) -> u32 {\n        // The build fingerprint in the input does the versioning.\n        1\n    }\n    fn convert(&self, input: &[u8]) -> anyhow::Result<Vec<u8>> {\n        self.ran.store(true, Ordering::Relaxed);\n        let shader = (self.translate)(&input[32..]).map_err(anyhow::Error::msg)?;\n        Ok(encode(&shader))\n    }\n}\n\nfn cached(\n    cache: &Cache,\n    build: &[u8; 32],\n    container: &[u8],\n    translate: impl Fn(&[u8]) -> Result<HostShader, String> + Send + Sync,\n) -> Result<HostShader, String> {\n    let input = [&build[..], container].concat();\n    let converter = Translate {\n        translate,\n        ran: AtomicBool::new(false),\n    };\n    for _ in 0..2 {\n        let path = cache\n            .get_or_convert(&converter, &input)\n            .map_err(|e| format!(\"{e:#}\"))?;\n        if let Some(shader) = std::fs::read(&path).ok().and_then(|b| decode(&b)) {\n            let (counter, what) = if converter.ran.load(Ordering::Relaxed) {\n                (&MISSES, \"translated and cached\")\n            } else {\n                (&HITS, \"from the cache\")\n            };\n            counter.fetch_add(1, Ordering::Relaxed);\n            tracing::debug!(path = %path.display(), \"shader {what}\");\n            return Ok(shader);\n        }\n        tracing::debug!(path = %path.display(), \"unreadable shader cache entry; translating again\");\n        let _ = std::fs::remove_file(&path);\n    }\n    MISSES.fetch_add(1, Ordering::Relaxed);\n    (converter.translate)(container)\n}\n\n",
         "struct Translate<F> {\n    translate: F,\n    ran: AtomicBool,\n    // Retain a successful translation until the cache has published it.\n    // Disk I/O is optional for gameplay, but not for offline warming.\n    completed: std::sync::Mutex<Option<HostShader>>,\n}\n\nimpl<F: Fn(&[u8]) -> Result<HostShader, String> + Send + Sync> Converter for Translate<F> {\n    fn id(&self) -> &'static str {\n        \"shader.dxil\"\n    }\n    fn version(&self) -> u32 {\n        // The build fingerprint in the input does the versioning.\n        1\n    }\n    fn convert(&self, input: &[u8]) -> anyhow::Result<Vec<u8>> {\n        self.ran.store(true, Ordering::Relaxed);\n        let mut completed = self.completed.lock().unwrap_or_else(|e| e.into_inner());\n        *completed = None;\n        let shader = (self.translate)(&input[32..]).map_err(anyhow::Error::msg)?;\n        let bytes = encode(&shader);\n        *completed = Some(shader);\n        Ok(bytes)\n    }\n}\n\nfn cached(\n    cache: &Cache,\n    build: &[u8; 32],\n    container: &[u8],\n    translate: impl Fn(&[u8]) -> Result<HostShader, String> + Send + Sync,\n) -> Result<HostShader, String> {\n    cached_with_policy(cache, build, container, translate, true)\n}\n\nfn cached_with_policy(\n    cache: &Cache,\n    build: &[u8; 32],\n    container: &[u8],\n    translate: impl Fn(&[u8]) -> Result<HostShader, String> + Send + Sync,\n    allow_uncached: bool,\n) -> Result<HostShader, String> {\n    let input = [&build[..], container].concat();\n    let converter = Translate {\n        translate,\n        ran: AtomicBool::new(false),\n        completed: std::sync::Mutex::new(None),\n    };\n    for _ in 0..2 {\n        let path = match cache.get_or_convert(&converter, &input) {\n            Ok(path) => path,\n            Err(e) => {\n                // A conversion failure has no completed shader. A publication\n                // failure after conversion must not permanently disable a\n                // valid shader for this gameplay session.\n                if allow_uncached {\n                    let completed = converter.completed.lock()\n                        .unwrap_or_else(|e| e.into_inner()).take();\n                    if let Some(shader) = completed {\n                        MISSES.fetch_add(1, Ordering::Relaxed);\n                        tracing::warn!(error = %e, \"shader cache publication failed; using uncached translation\");\n                        return Ok(shader);\n                    }\n                }\n                return Err(format!(\"{e:#}\"));\n            }\n        };\n        if let Some(shader) = std::fs::read(&path).ok().and_then(|b| decode(&b)) {\n            let (counter, what) = if converter.ran.load(Ordering::Relaxed) {\n                (&MISSES, \"translated and cached\")\n            } else {\n                (&HITS, \"from the cache\")\n            };\n            counter.fetch_add(1, Ordering::Relaxed);\n            tracing::debug!(path = %path.display(), \"shader {what}\");\n            return Ok(shader);\n        }\n        // If this call just translated successfully, use that result for\n        // gameplay rather than translating a second time. The broken\n        // entry is still removed so another process can rebuild it.\n        tracing::debug!(path = %path.display(), \"unreadable shader cache entry; translating again\");\n        let _ = std::fs::remove_file(&path);\n        if allow_uncached {\n            let completed = converter.completed.lock()\n                .unwrap_or_else(|e| e.into_inner()).take();\n            if let Some(shader) = completed {\n                MISSES.fetch_add(1, Ordering::Relaxed);\n                return Ok(shader);\n            }\n        }\n    }\n    if !allow_uncached {\n        return Err(\"shader cache entry could not be read after two attempts\".to_owned());\n    }\n    MISSES.fetch_add(1, Ordering::Relaxed);\n    (converter.translate)(container)\n}\n\n"),
